===== ValidateOwnerFields =====
package org.springframework.samples.petclinic.rest.function.owner;

import java.util.ArrayList;
import java.util.List;
import java.util.regex.Pattern;

import net.officefloor.plugin.variable.Out;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.samples.petclinic.rest.escalation.OwnerFieldsInvalidException;
import org.springframework.web.bind.annotation.RequestBody;

/**
 * First step of {@code POST /api/owners}: rejects a request that is missing or blank in any of
 * firstName, lastName, address, city or telephone. Throwing lists every offending field, so the
 * client sees them all at once. It also normalizes the telephone into E.164 form (keeping a leading
 * '+' and country code when present, otherwise assuming '+61' and dropping a single leading '0'),
 * rejecting with 400 when it cannot form a valid E.164 number; the normalized value is
 * written back onto the body. When an optional {@code email} is present it must be a syntactically
 * valid address (else 400); it is lower-cased and written back. On success it publishes the body for
 * {@link BuildOwner} to map.
 */
public class ValidateOwnerFields {

    /** Syntactic email check: a non-empty local part, an {@code @}, then a dotted domain. */
    private static final Pattern EMAIL = Pattern.compile("^[^@\\s]+@[^@\\s.]+(\\.[^@\\s.]+)+$");

    public void service(@RequestBody OwnerFieldsDto request, Out<OwnerFieldsDto> validated)
            throws OwnerFieldsInvalidException {
        List<String> errors = new ArrayList<>();
        checkPresent("firstName", request.getFirstName(), errors);
        checkPresent("lastName", request.getLastName(), errors);
        checkPresent("address", request.getAddress(), errors);
        checkPresent("city", request.getCity(), errors);
        checkPresent("telephone", request.getTelephone(), errors);
        if (!errors.isEmpty()) {
            throw new OwnerFieldsInvalidException(errors);
        }
        String telephone = E164Telephone.normalize(request.getTelephone());
        if (telephone == null) {
            throw new OwnerFieldsInvalidException(List.of("telephone"));
        }
        request.setTelephone(telephone);
        String email = request.getEmail();
        if (email != null && !email.trim().isEmpty()) {
            email = email.trim();
            if (!EMAIL.matcher(email).matches()) {
                throw new OwnerFieldsInvalidException(List.of("email"));
            }
            request.setEmail(email.toLowerCase());
        }
        validated.set(request);
    }

    private static void checkPresent(String field, String value, List<String> errors) {
        if (value == null || value.trim().isEmpty()) {
            errors.add(field);
        }
    }
}
===== CheckOwnerHouseholdUnique =====
package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.samples.petclinic.rest.escalation.OwnerHouseholdConflictException;

/**
 * Runs after {@link CheckOwnerTelephoneUnique} and before {@link BuildOwner}: rejects the request
 * with 409 when another owner already has the same last name at the same address. Both the last
 * name and the address are compared case-insensitively with runs of whitespace collapsed to a
 * single space, so differently-cased or -spaced duplicates are still caught. A request may opt out
 * of the check by setting {@code sharesHousehold: true} (two owners sharing one household).
 */
public class CheckOwnerHouseholdUnique {

    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
            throws OwnerHouseholdConflictException {
        if (Boolean.TRUE.equals(request.getSharesHousehold())) {
            return;
        }
        String lastName = normalize(request.getLastName());
        String address = normalize(request.getAddress());
        for (Owner existing : ownerRepository.findAll()) {
            if (lastName.equals(normalize(existing.getLastName()))
                    && address.equals(normalize(existing.getAddress()))) {
                throw new OwnerHouseholdConflictException("An owner with last name "
                        + request.getLastName() + " already lives at " + request.getAddress());
            }
        }
    }

    /** Lower-case, trim, and collapse internal whitespace runs to a single space. */
    private static String normalize(String value) {
        if (value == null) {
            return "";
        }
        return value.trim().replaceAll("\\s+", " ").toLowerCase();
    }
}
